class TestSecureKeyLifecycle:
    """Validates INV-001: SecureKey creation, immutability, and state transitions."""

    def test_key_creation_valid(self, secure_key_factory):
        """Test valid key creation with all parameters."""
        key = secure_key_factory()
        assert key.key_id is not None
        assert len(key.material) == 32
        assert key.ttl == KEY_ROTATION_TTL
        assert key.status == KeyStatus.ACTIVE
        assert key.created_at > 0
        assert key.expires_at > key.created_at

    def test_key_creation_custom_ttl(self, secure_key_factory):
        """Test key creation with custom TTL."""
        custom_ttl = 30.0
        key = secure_key_factory(ttl=custom_ttl)
        assert key.ttl == custom_ttl
        assert key.expires_at - key.created_at == pytest.approx(custom_ttl)

    def test_key_creation_invalid_material_length(self, secure_key_factory):
        """Test rejection of invalid material length."""
        with pytest.raises(ValueError, match="Material must be exactly 32 bytes"):
            secure_key_factory(material=os.urandom(16))

    def test_key_creation_empty_material(self, secure_key_factory):
        """Test rejection of empty material."""
        with pytest.raises(ValueError, match="Material must be exactly 32 bytes"):
            secure_key_factory(material=b'')

    def test_key_creation_invalid_ttl(self, secure_key_factory):
        """Test rejection of non-positive TTL."""
        with pytest.raises(ValueError, match="TTL must be positive"):
            secure_key_factory(ttl=0)
        with pytest.raises(ValueError, match="TTL must be positive"):
            secure_key_factory(ttl=-10)

    def test_key_creation_invalid_status(self, secure_key_factory):
        """Test rejection of invalid status enum."""
        with pytest.raises(ValueError, match="Invalid key status"):
            secure_key_factory(status="INVALID_STATUS")

    def test_key_immutability(self, secure_key_factory):
        """Test that SecureKey is immutable after creation."""
        key = secure_key_factory()
        with pytest.raises(FrozenInstanceError):
            key.key_id = "modified"
        with pytest.raises(FrozenInstanceError):
            key.material = b"modified"
        with pytest.raises(FrozenInstanceError):
            key.status = KeyStatus.REVOKED

    def test_key_status_transitions(self, secure_key_factory):
        """Test valid status transitions."""
        key = secure_key_factory()
        # ACTIVE -> ROTATING
        key = key.with_status(KeyStatus.ROTATING)
        assert key.status == KeyStatus.ROTATING
        # ROTATING -> ACTIVE
        key = key.with_status(KeyStatus.ACTIVE)
        assert key.status == KeyStatus.ACTIVE
        # ACTIVE -> REVOKED
        key = key.with_status(KeyStatus.REVOKED)
        assert key.status == KeyStatus.REVOKED
        # REVOKED -> EXPIRED
        key = key.with_status(KeyStatus.EXPIRED)
        assert key.status == KeyStatus.EXPIRED

    def test_key_invalid_status_transition(self, secure_key_factory):
        """Test rejection of invalid status transitions."""
        key = secure_key_factory()
        # EXPIRED -> ACTIVE is invalid
        key = key.with_status(KeyStatus.EXPIRED)
        with pytest.raises(KeyRotationError, match="Invalid status transition"):
            key.with_status(KeyStatus.ACTIVE)

    def test_key_expiry_check(self, secure_key_factory):
        """Test key expiry detection."""
        key = secure_key_factory(ttl=0.1)
        assert not key.is_expired()
        time.sleep(0.2)
        assert key.is_expired()

    def test_key_serialization_roundtrip(self, secure_key_factory):
        """Test key serialization and deserialization."""
        key = secure_key_factory()
        serialized = key.to_bytes()
        deserialized = SecureKey.from_bytes(serialized)
        assert deserialized == key

    def test_key_serialization_invalid_data(self):
        """Test rejection of malformed serialized data."""
        with pytest.raises(ValueError, match="Invalid serialized key data"):
            SecureKey.from_bytes(b"invalid_data")

    def test_key_material_zeroization(self, secure_key_factory):
        """Test that key material is zeroized on revocation."""
        key = secure_key_factory()
        key.zeroize()
        assert all(b == 0 for b in key.material)
        assert key.status == KeyStatus.REVOKED


