class TestPropertyValidation:
    """Validates INV-003: Bounded buffer invariants, TTL enforcement, memory safety."""

    @pytest.mark.asyncio
    async def test_buffer_invariant_never_exceeds_max(self, gateway_instance, mock_kyber_success):
        """Property: active_keys never exceeds MAX_ACTIVE_KEYS."""
        for _ in range(MAX_ACTIVE_KEYS * 2):
            try:
                await gateway_instance.generate_key()
            except GatewayError:
                break
        assert gateway_instance.active_keys <= MAX_ACTIVE_KEYS

    @pytest.mark.asyncio
    async def test_ttl_enforcement_property(self, gateway_instance, mock_kyber_success):
        """Property: all keys have positive TTL and future expiry."""
        for _ in range(100):
            key = await gateway_instance.generate_key()
            assert key.ttl > 0
            assert key.expires_at > time.time()

    @pytest.mark.asyncio
    async def test_memory_safety_no_leaks(self, gateway_instance, mock_kyber_success):
        """Property: no memory leaks after repeated operations."""
        gc.collect()
        baseline = len(gc.get_objects())
        for _ in range(100):
            key = await gateway_instance.generate_key()
            await gateway_instance.revoke_key(key.key_id)
        gc.collect()
        after = len(gc.get_objects())
        # Allow some overhead for internal structures
        assert after - baseline < 1000

    @pytest.mark.asyncio
    async def test_key_id_uniqueness(self, gateway_instance, mock_kyber_success):
        """Property: all generated key IDs are unique."""
        key_ids = set()
        for _ in range(100):
            key = await gateway_instance.generate_key()
            assert key.key_id not in key_ids
            key_ids.add(key.key_id)

    @pytest.mark.asyncio
    async def test_material_entropy(self, gateway_instance, mock_kyber_success):
        """Property: generated key material has sufficient entropy."""
        for _ in range(10):
            key = await gateway_instance.generate_key()
            # Check that material is not all zeros or all ones
            assert any(b != 0 for b in key.material)
            assert any(b != 255 for b in key.material)
            # Check byte distribution is not degenerate
            unique_bytes = len(set(key.material))
            assert unique_bytes >= 8  # At least 8 unique bytes in 32-byte key

    @pytest.mark.asyncio
    async def test_serialization_roundtrip_property(self, gateway_instance, mock_kyber_success):
        """Property: serialization roundtrip preserves all fields."""
        for _ in range(50):
            key = await gateway_instance.generate_key()
            serialized = key.to_bytes()
            deserialized = SecureKey.from_bytes(serialized)
            assert deserialized.key_id == key.key_id
            assert deserialized.material == key.material
            assert deserialized.ttl == key.ttl
            assert deserialized.status == key.status
            assert deserialized.created_at == key.created_at
            assert deserialized.expires_at == key.expires_at


