class TestStressAndChaos:
    """Validates INV-004: Stress tolerance and chaos resilience."""

    @pytest.mark.asyncio
    async def test_concurrent_key_generation(self, gateway_instance, mock_kyber_success):
        """Stress: 10k concurrent key operations."""
        tasks = [gateway_instance.generate_key() for _ in range(10000)]
        results = await asyncio.gather(*tasks, return_exceptions=True)
        success_count = sum(1 for r in results if isinstance(r, SecureKey))
        error_count = sum(1 for r in results if isinstance(r, Exception))
        assert success_count + error_count == 10000
        assert gateway_instance.active_keys == success_count
        assert success_count <= MAX_ACTIVE_KEYS

    @pytest.mark.asyncio
    async def test_concurrent_key_rotation(self, gateway_instance, mock_kyber_success):
        """Stress: concurrent rotation of multiple keys."""
        keys = [await gateway_instance.generate_key() for _ in range(100)]
        tasks = [gateway_instance.rotate_key(key.key_id) for key in keys]
        results = await asyncio.gather(*tasks, return_exceptions=True)
        success_count = sum(1 for r in results if isinstance(r, SecureKey))
        assert success_count == 100

    @pytest.mark.asyncio
    async def test_chaos_kyber_failure_recovery(self, gateway_instance, mock_kyber_failure):
        """Chaos: kyber failure doesn't corrupt gateway state."""
        with pytest.raises(KyberOperationError):
            await gateway_instance.generate_key()
        assert gateway_instance.active_keys == 0
        assert gateway_instance.is_initialized

    @pytest.mark.asyncio
    async def test_chaos_socket_exhaustion(self, gateway_instance, mock_socket_exhaustion):
        """Chaos: socket exhaustion handled gracefully."""
        with pytest.raises(SocketCleanupError):
            await gateway_instance.generate_key()
        assert gateway_instance.active_keys == 0

    @pytest.mark.asyncio
    async def test_chaos_partial_failure_batch(self, gateway_instance, mock_kyber_success):
        """Chaos: partial failures in batch operations."""
        # Simulate intermittent failures
        original_encap = mock_kyber_success['encapsulate']
        call_count = 0

        async def flaky_encap(*args, **kwargs):
            nonlocal call_count
            call_count += 1
            if call_count % 3 == 0:
                raise KyberOperationError("Intermittent failure")
            return await original_encap(*args, **kwargs)

        mock_kyber_success['encapsulate'].side_effect = flaky_encap
        results = []
        for _ in range(30):
            try:
                key = await gateway_instance.generate_key()
                results.append(key)
            except KyberOperationError:
                pass
        assert len(results) > 0
        assert gateway_instance.active_keys == len(results)

    @pytest.mark.asyncio
    async def test_stress_cleanup_interval(self, gateway_instance, mock_kyber_success):
        """Stress: cleanup interval handles large key volumes."""
        # Generate keys up to capacity
        for _ in range(MAX_ACTIVE_KEYS):
            await gateway_instance.generate_key()
        # Force all keys to expire
        for key_id in list(gateway_instance._keys.keys()):
            key = gateway_instance._keys[key_id]
            expired = key.with_status(KeyStatus.EXPIRED)
            gateway_instance._keys[key_id] = expired
        await gateway_instance.cleanup_expired_keys()
        assert gateway_instance.active_keys == 0

    @pytest.mark.asyncio
    async def test_chaos_corrupted_serialization(self, gateway_instance):
        """Chaos: corrupted serialized data doesn't crash gateway."""
        corrupted = b'\x00' * 100
        with pytest.raises(ValueError):
            SecureKey.from_bytes(corrupted)

    @pytest.mark.asyncio
    async def test_stress_memory_pressure(self, gateway_instance, mock_kyber_success):
        """Stress: memory pressure with large key volumes."""
        import tracemalloc
        tracemalloc.start()
        for _ in range(1000):
            key = await gateway_instance.generate_key()
            await gateway_instance.revoke_key(key.key_id)
        current, peak = tracemalloc.get_traced_memory()
        tracemalloc.stop()
        # Peak memory should be bounded (e.g., < 100MB)
        assert peak < 100 * 1024 * 1024


