class TestIntegration:
    """End-to-end integration tests with real async operations."""

    @pytest.mark.asyncio
    async def test_full_key_lifecycle_integration(self, gateway_instance, mock_kyber_success):
        """Integration: complete key lifecycle from generation to revocation."""
        # Generate
        key = await gateway_instance.generate_key()
        assert key.status == KeyStatus.ACTIVE

        # Retrieve
        retrieved = await gateway_instance.get_key(key.key_id)
        assert retrieved == key

        # Rotate
        rotated = await gateway_instance.rotate_key(key.key_id)
        assert rotated.key_id != key.key_id

        # Revoke
        await gateway_instance.revoke_key(rotated.key_id)
        assert gateway_instance.active_keys == 0

    @pytest.mark.asyncio
    async def test_gateway_with_uvloop(self, event_loop_policy, mock_kyber_success):
        """Integration: gateway operations with uvloop event loop."""
        if uvloop is None:
            pytest.skip("uvloop not available")
        gw = QKDGateway()
        await gw.initialize()
        try:
            key = await gw.generate_key()
            assert key is not None
            assert gw.active_keys == 1
        finally:
            await gw.shutdown()

    @pytest.mark.asyncio
    async def test_concurrent_gateway_instances(self, mock_kyber_success):
        """Integration: multiple gateway instances operate independently."""
        gw1 = QKDGateway()
        gw2 = QKDGateway()
        await gw1.initialize()
        await gw2.initialize()
        try:
            key1 = await gw1.generate_key()
            key2 = await gw2.generate_key()
            assert key1.key_id != key2.key_id
            assert gw1.active_keys == 1
            assert gw2.active_keys == 1
        finally:
            await gw1.shutdown()
            await gw2.shutdown()

    @pytest.mark.asyncio
    async def test_gateway_error_handling(self, gateway_instance):
        """Integration: error handling for various failure modes."""
        # Invalid key ID
        with pytest.raises(GatewayError):
            await gateway_instance.get_key("invalid")
        # Empty key ID
        with pytest.raises(GatewayError):
            await gateway_instance.get_key("")
        # None key ID
        with pytest.raises(GatewayError):
            await gateway_instance.get_key(None)


